+<?php
+
+/* Maintain the notes of a stock item: add, view, edit and delete */
+
+require(__DIR__ . '/includes/session.php');
+
+$Title = __('Item Notes');
+$ViewTopic = 'Inventory';
+$BookMark = 'StockNotes';
+include('includes/header.php');
+
+if (isset($_GET['StockID'])) {
+	$StockID = trim(mb_strtoupper($_GET['StockID']));
+} elseif (isset($_POST['StockID'])) {
+	$StockID = trim(mb_strtoupper($_POST['StockID']));
+}
+
+echo '<a href="' . $RootPath . '/SelectProduct.php" class="toplink">' . __('Back to Items') . '</a>';
+
+echo '<p class="page_title_text"><img alt="" src="', $RootPath, '/css/', $Theme,
+	'/images/inventory.png" title="', $Title, '" /> ', $Title, '</p>';
+
+if (!isset($StockID) or $StockID == '') {
+	prnMsg(__('An item must first be selected before this page is called') . '. ' . __('The product selection page should call this page with a valid product code'), 'error');
+	include('includes/footer.php');
+	exit();
+}
+
+$Result = DB_query("SELECT description FROM stockmaster WHERE stockid='" . $StockID . "'");
+if (DB_num_rows($Result) == 0) {
+	prnMsg(__('The part code entered does not exist in the database') . ': ' . $StockID, 'error');
+	include('includes/footer.php');
+	exit();
+}
+$MyRow = DB_fetch_row($Result);
+$PartDescription = $MyRow[0];
+
+$SelfURL = htmlspecialchars($_SERVER['PHP_SELF'], ENT_QUOTES, 'UTF-8') . '?StockID=' . urlencode($StockID);
+
+if (isset($_POST['submit'])) {
+
+	$Note = trim($_POST['Note']);
+	$NoteID = isset($_POST['NoteID']) ? (int) $_POST['NoteID'] : 0;
+
+	if ($Note == '') {
+		prnMsg(__('The note cannot be empty'), 'error');
+		$_GET['Edit'] = $NoteID; // keep the form on the same note
+	} elseif ($NoteID > 0) {
+		DB_query("UPDATE stockitemnotes
+					SET note = '" . $Note . "'
+					WHERE noteid = " . $NoteID . "
+					AND stockid = '" . $StockID . "'",
+				__('The note could not be updated'));
+		prnMsg(__('The note has been updated'), 'success');
+	} else {
+		DB_query("INSERT INTO stockitemnotes (stockid, note, userid, dateadded)
+					VALUES ('" . $StockID . "',
+						'" . $Note . "',
+						'" . $_SESSION['UserID'] . "',
+						'" . date('Y-m-d H:i:s') . "')",
+				__('The note could not be added'));
+		prnMsg(__('The note has been added'), 'success');
+	}
+	if ($Note != '') {
+		unset($_POST['Note'], $_POST['NoteID']);
+	}
+
+} elseif (isset($_GET['Delete'])) {
+
+	DB_query("DELETE FROM stockitemnotes
+				WHERE noteid = " . (int) $_GET['Delete'] . "
+				AND stockid = '" . $StockID . "'",
+			__('The note could not be deleted'));
+	prnMsg(__('The note has been deleted'), 'success');
+}
+
+// the note being edited, if any
+$EditID = 0;
+$EditText = '';
+if (isset($_GET['Edit']) or isset($_POST['NoteID'])) {
+	$EditID = (int) (isset($_GET['Edit']) ? $_GET['Edit'] : $_POST['NoteID']);
+	if (isset($_POST['Note'])) {
+		$EditText = $_POST['Note'];
+	} else {
+		$Result = DB_query("SELECT note FROM stockitemnotes
+							WHERE noteid = " . $EditID . "
+							AND stockid = '" . $StockID . "'");
+		if (DB_num_rows($Result) == 0) {
+			$EditID = 0;
+		} else {
+			$MyRow = DB_fetch_row($Result);
+			$EditText = $MyRow[0];
+		}
+	}
+}
+
+$Result = DB_query("SELECT noteid, note, userid, dateadded
+					FROM stockitemnotes
+					WHERE stockid = '" . $StockID . "'
+					ORDER BY dateadded, noteid");
+
+if (DB_num_rows($Result) > 0) {
+	echo '<table class="selection">
+			<thead>
+				<tr>
+					<th colspan="5">' . $StockID . ' - ' . $PartDescription . '</th>
+				</tr>
+				<tr>
+					<th>' . __('Date') . '</th>
+					<th>' . __('User') . '</th>
+					<th>' . __('Note') . '</th>
+					<th colspan="2"></th>
+				</tr>
+			</thead>
+			<tbody>';
+	while ($MyRow = DB_fetch_array($Result)) {
+		echo '<tr class="striped_row">
+				<td>' . ConvertSQLDate(mb_substr($MyRow['dateadded'], 0, 10)) . '</td>
+				<td>' . $MyRow['userid'] . '</td>
+				<td>' . nl2br($MyRow['note']) . '</td>
+				<td><a href="' . $SelfURL . '&amp;Edit=' . $MyRow['noteid'] . '">' . __('Edit') . '</a></td>
+				<td><a href="' . $SelfURL . '&amp;Delete=' . $MyRow['noteid'] . '" onclick="return confirm(\'' . __('Are you sure you wish to delete this note?') . '\');">' . __('Delete') . '</a></td>
+			</tr>';
+	}
+	echo '</tbody></table>';
+} else {
+	prnMsg(__('There are no notes for this item'), 'info');
+}
+
+echo '<form method="post" action="' . $SelfURL . '">
+	<input type="hidden" name="FormID" value="' . $_SESSION['FormID'] . '" />
+	<input type="hidden" name="StockID" value="' . $StockID . '" />';
+if ($EditID > 0) {
+	echo '<input type="hidden" name="NoteID" value="' . $EditID . '" />';
+}
+echo '<fieldset>
+		<legend>' . ($EditID > 0 ? __('Edit Note') : __('New Note')) . '</legend>
+		<field>
+			<label for="Note">' . __('Note') . ':</label>
+			<textarea name="Note" id="Note" rows="5" cols="60" required="required">' . $EditText . '</textarea>
+		</field>
+	</fieldset>
+	<div class="centre">
+		<input type="submit" name="submit" value="' . ($EditID > 0 ? __('Update Note') : __('Add Note')) . '" />';
+if ($EditID > 0) {
+	echo ' <a href="' . $SelfURL . '">' . __('Cancel') . '</a>';
+}
+echo '</div>
+	</form>';
+
+include('includes/footer.php');
