+
+echo '<p class="page_title_text"><img alt="" src="' . $RootPath . '/css/' . $Theme .
+		'/images/inventory.png" title="' . $Title . '" /> ' . $Title . '</p>';
+
+// The CSV file has one note per row: "StockID","Note". An item with several notes has several rows.
+// The items must already exist (import them first with Z_ImportStocks.php). Notes are added to
+// any notes the item already has; the whole file is rolled back if any row is invalid.
+
+$FieldHeadings = array(
+	'StockID', // 0
+	'Note'     // 1
+);
+
+if (isset($_FILES['userfile']) and $_FILES['userfile']['name']) {
+
+	$InputError = 0;
+	$FileName = $_FILES['userfile']['name'];
+	$FileHandle = fopen($_FILES['userfile']['tmp_name'], 'r');
+
+	$HeadRow = fgetcsv($FileHandle, 0, ',', '"');
+	if ($HeadRow !== false and substr($HeadRow[0], 0, 3) === "\xef\xbb\xbf") {
+		$HeadRow[0] = substr($HeadRow[0], 3);
+	}
+
+	if ($HeadRow === false or count($HeadRow) != count($FieldHeadings)
+		or mb_strtoupper(trim($HeadRow[0])) != mb_strtoupper($FieldHeadings[0])
