+			prnMsg(__('Row') . ' ' . $Row . ': ' . count($FieldHeadings) . ' ' . __('fields required') . ', ' . count($MyRow) . ' ' . __('fields received'), 'error');
+			$InputError = 1;
+			break;
+		}
+
+		$StockID = mb_strtoupper(trim($MyRow[0]));
+		$Note = trim($MyRow[1]);
+		if ($Note == '') {
+			continue; // nothing to store for this item
+		}
+
+		$Result = DB_query("SELECT stockid FROM stockmaster WHERE stockid='" . DB_escape_string($StockID) . "'");
