+			prnMsg(__('Row') . ' ' . $Row . ': ' . __('Stock item') . ' ' . htmlspecialchars($StockID, ENT_QUOTES, 'UTF-8') . ' ' . __('does not exist'), 'error');
+			$InputError = 1;
+			break;
+		}
+
+		// stored the same way as notes entered on StockNotes.php (html escaped)
+		DB_query("INSERT INTO stockitemnotes (stockid, note, userid, dateadded)
+					VALUES ('" . DB_escape_string($StockID) . "',
+						'" . DB_escape_string(htmlspecialchars($Note, ENT_QUOTES, 'UTF-8')) . "',
+						'" . $_SESSION['UserID'] . "',
+						'" . date('Y-m-d H:i:s') . "')",
+				__('The note could not be added because'));
+		$Imported++;
+	}
+	fclose($FileHandle);
+
+	if ($InputError == 1) {
+		prnMsg(__('Failed on row') . ' ' . $Row . '. ' . __('Batch import has been rolled back.'), 'error');
+		DB_Txn_Rollback();
+	} else {
+		DB_Txn_Commit();
+		prnMsg(__('Batch Import of') . ' ' . htmlspecialchars($FileName, ENT_QUOTES, 'UTF-8') . ' ' . __('has been completed') . '. ' . $Imported . ' ' . __('notes imported') . '.', 'success');
+	}
+
+} elseif (isset($_GET['gettemplate'])) {
+
+	echo '<br /><br /><br />"' . implode('","', $FieldHeadings) . '"<br /><br /><br />';
+
+} else {
+
+	echo '<br />
+		<a href="' . $RootPath . '/Z_ImportStockNotes.php?gettemplate=1">' . __('Get Import Template') . '</a>
